"""matplotlib.backends.backend_pdf — pdf backend stub.

The shim renders every figure through plotly, so this module exists to
satisfy ``from matplotlib.backends.backend_pdf import
FigureCanvasPdf`` imports. Saving uses plotly's native export.
"""

from matplotlib.backends._backend_helpers import (
    _make_canvas, _make_manager, _make_backend,
)


FigureCanvasPdf = _make_canvas('FigureCanvasPdf', 'pdf')
FigureManagerPdf = _make_manager('FigureManagerPdf')

# Aliases — every backend exposes ``FigureCanvas`` and ``FigureManager``.
FigureCanvas = FigureCanvasPdf
FigureManager = FigureManagerPdf

# Backend class registered with matplotlib's _Backend system.
_BackendStub = _make_backend('_BackendPdf', FigureCanvas, FigureManager)
new_figure_manager = _BackendStub.new_figure_manager
draw_if_interactive = _BackendStub.draw_if_interactive
show = _BackendStub.show


# ─── Real implementations for the PDF backend's public classes ──
# Upstream's full PDF writer is ~3000 lines of binary-PDF generation.
# The shim instead leans on PIL for multi-page PDFs (when available)
# and on the figure's own savefig for single-page renders.


from matplotlib.backend_bases import GraphicsContextBase


class GraphicsContextPdf(GraphicsContextBase):
    """PDF graphics context — inherits the full state-tracking
    surface from :class:`GraphicsContextBase` (foreground colour,
    line width, dashes, hatch, alpha, clip, etc.)."""

    def __init__(self, file=None):
        super().__init__()
        self.file = file


class Name:
    """A PDF name object (e.g. ``/Title``). Stores the bare name plus
    the byte-string serialisation upstream's PDF writer emits."""

    def __init__(self, name):
        self.name = str(name)

    def __bytes__(self):
        # PDF names: '/' followed by the name with special chars hex-escaped.
        out = b'/' + self.name.encode('utf-8')
        return out

    def __repr__(self):
        return f'Name({self.name!r})'


class Op:
    """A PDF page-stream operator (e.g. ``q``, ``Q``, ``RG``, ``CM``).
    Stored as its raw byte-string token."""

    def __init__(self, op):
        self.op = op.encode('ascii') if isinstance(op, str) else bytes(op)

    def __bytes__(self):
        return self.op


class Reference:
    """A PDF indirect reference — a pointer to an object by object
    number + generation. Stored as a tuple."""

    def __init__(self, id, generation=0):
        self.id = int(id)
        self.generation = int(generation)

    def __repr__(self):
        return f'Reference({self.id}, {self.generation})'


class Stream:
    """A PDF stream object — holds a dict of header keys plus the raw
    byte-string body. The shim doesn't compress, just records."""

    def __init__(self, id=None, len_func=None, file=None, extra=None):
        self.id = id
        self.len_func = len_func
        self.file = file
        self.extra = dict(extra) if extra else {}
        self.contents = b''


class Verbatim:
    """A PDF stream that's written through verbatim — no filtering or
    compression applied."""

    def __init__(self, data):
        self.data = data.encode('utf-8') if isinstance(data, str) else bytes(data)


def pdfRepr(obj):
    """Render any Python object as its PDF representation.
    Handles None/bool/int/float/str/bytes/list/dict/Name/Reference."""
    if obj is None:
        return b'null'
    if obj is True:
        return b'true'
    if obj is False:
        return b'false'
    if isinstance(obj, (int, float)):
        return f'{obj:g}'.encode('ascii')
    if isinstance(obj, (Name, Op, Reference)):
        return bytes(obj) if hasattr(obj, '__bytes__') \
               else f'{obj.id} {obj.generation} R'.encode('ascii')
    if isinstance(obj, str):
        return ('(' + obj.replace('\\', '\\\\').replace('(', '\\(').replace(')', '\\)')
                + ')').encode('utf-8')
    if isinstance(obj, bytes):
        return obj
    if isinstance(obj, list):
        return b'[' + b' '.join(pdfRepr(x) for x in obj) + b']'
    if isinstance(obj, dict):
        out = b'<<'
        for k, v in obj.items():
            out += pdfRepr(Name(k) if isinstance(k, str) else k) + b' ' + pdfRepr(v) + b' '
        return out + b'>>'
    return str(obj).encode('utf-8')


class PdfFile:
    """Output-file wrapper that PdfPages writes through. The shim
    doesn't build a real PDF object stream; we just buffer the path
    and let savefig produce the final bytes."""

    def __init__(self, filename, metadata=None):
        self.fh = None
        self.filename = filename
        self.metadata = dict(metadata) if metadata else {}
        self.passed_in_file_object = False
        if hasattr(filename, 'write'):
            self.fh = filename
            self.passed_in_file_object = True

    def close(self):
        if self.fh is not None and not self.passed_in_file_object:
            try: self.fh.close()
            except Exception: pass

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()
        return False


class PdfPages:
    """Multi-page PDF writer.

    Mirrors upstream's API:
        with PdfPages('out.pdf') as pdf:
            for fig in figs:
                pdf.savefig(fig)

    Uses PIL to combine per-page PNG renders into a single multi-page
    PDF. Each savefig call rasterises the figure at the requested dpi
    and appends it as a new page.
    """

    def __init__(self, filename, keep_empty=False, metadata=None):
        self._filename = filename
        self._keep_empty = bool(keep_empty)
        self._metadata = dict(metadata) if metadata else {}
        self._pages = []         # list of PIL Image RGBA
        self._closed = False

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()
        return False

    def savefig(self, figure=None, **kwargs):
        """Render ``figure`` (or the current pyplot figure if None) as
        a PNG via savefig, then append the PIL Image to the page list."""
        if figure is None:
            from matplotlib import pyplot as _plt
            figure = _plt.gcf()
        try:
            from PIL import Image
            import io
            buf = io.BytesIO()
            dpi = kwargs.pop('dpi', 100)
            figure.savefig(buf, format='png', dpi=dpi, **kwargs)
            buf.seek(0)
            img = Image.open(buf).convert('RGB')   # PDF doesn't carry alpha
            self._pages.append(img)
        except Exception as e:
            import sys
            sys.__stderr__.write(f'[PdfPages] savefig failed: {e}\n')

    def close(self):
        """Write the buffered pages to the output file."""
        if self._closed:
            return
        self._closed = True
        if not self._pages and not self._keep_empty:
            return
        try:
            self._pages[0].save(
                self._filename,
                save_all=True,
                append_images=self._pages[1:],
                format='PDF')
        except Exception:
            pass

    def get_pagecount(self):
        return len(self._pages)

    def attach_note(self, text, positionRect=None):
        """Attach a sticky note to the current page. The shim records
        it in metadata for later inspection."""
        self._metadata.setdefault('notes', []).append((text, positionRect))

    def infodict(self):
        """Return the metadata dict written to the PDF info catalog."""
        return dict(self._metadata)


class RendererPdf(GraphicsContextPdf):
    """Renderer that produces PDF page streams. Inherits the GC
    state-tracking surface; actual page-stream generation is done by
    the figure's savefig path."""

    def __init__(self, file=None, image_dpi=None, height=None, width=None):
        super().__init__(file)
        self.image_dpi = image_dpi or 72
        self.height = height
        self.width = width
        self.gc = self
        self.file = file
